window.getArticlesBySection=function(section,limit){
  var db=typeof ARTICLES_DB!=="undefined"?ARTICLES_DB:ARTICLES_META;
  var arts=db.filter(function(a){return a.section===section;});
  arts.sort(function(a,b){return new Date(b.date)-new Date(a.date);});
  return limit?arts.slice(0,limit):arts;
};
window.getArticleBySlug=function(slug){
  var db=typeof ARTICLES_DB!=="undefined"?ARTICLES_DB:ARTICLES_META;
  return db.find(function(a){return a.slug===slug;});
};
window.getAllArticles=function(limit){
  var db=typeof ARTICLES_DB!=="undefined"?ARTICLES_DB:ARTICLES_META;
  var arts=[].concat(db);
  arts.sort(function(a,b){return new Date(b.date)-new Date(a.date);});
  return limit?arts.slice(0,limit):arts;
};
